div.script:
(function(){
 function init(){
  var root=document.getElementById('dt8-hb-pk'),form=document.getElementById('dt8-hb-pk-form');
  if(!root||!form||form.dataset.ready)return;
  form.dataset.ready='1';
  if(location.hash==='#dt8-hb-pk')root.open=true;
  window.addEventListener('hashchange',function(){if(location.hash==='#dt8-hb-pk')root.open=true;});
  var date=form.querySelector('[name="preferred_day"]'),zone=form.querySelector('[name="preferred_zone"]');
  function format(d){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');}
  var now=new Date();date.min=format(now);var future=new Date(now.getTime());future.setDate(future.getDate()+90);date.max=format(future);
  try{var tz=Intl.DateTimeFormat().resolvedOptions().timeZone;if(zone.querySelector('option[value="'+tz+'"]'))zone.value=tz;}catch(e){}
  var button=form.querySelector('button[type="submit"]'),feedback=form.querySelector('.dt8-hb-pk-feedback');
  var tokenKey='dt8-hb-pk-'+form.getAttribute('data-user-id');
  function token(){
    var saved='';try{saved=sessionStorage.getItem(tokenKey)||'';}catch(e){}
    if(saved)return saved;
    var key=(window.crypto&&crypto.randomUUID)?crypto.randomUUID():Date.now().toString(36)+'_'+Math.random().toString(36).slice(2);
    try{sessionStorage.setItem(tokenKey,key);}catch(e){}return key;
  }
  form.addEventListener('submit',async function(e){
   e.preventDefault();
   if(!form.reportValidity())return;
   button.disabled=true;feedback.textContent='Submitting your preferred time…';
   var payload={dt8_pk_request:true,dt8_pk_day:date.value,dt8_pk_time:form.querySelector('[name="preferred_time"]').value,
     dt8_pk_zone:zone.value,dt8_pk_duration:Number(form.querySelector('[name="preferred_duration"]').value),
     dt8_pk_topics:form.querySelector('[name="preferred_topics"]').value,
     dt8_pk_token:token()};
   try{
    var res=await fetch('/web/dataset/call_kw/ir.actions.server/run',{
      method:'POST',credentials:'same-origin',
      headers:{'Content-Type':'application/json','Accept':'application/json',
        'X-CSRF-Token':form.querySelector('[name="csrf_token"]').value},
      body:JSON.stringify({jsonrpc:'2.0',method:'call',params:{model:'ir.actions.server',method:'run',args:[[1768]],kwargs:{context:payload}}})
    });
    if(!res.ok)throw new Error('The request could not be received. Please try again.');
    var data=await res.json();
    if(data.error)throw new Error((data.error.data&&data.error.data.message)||data.error.message||'The request could not be received.');
    if(!data.result||data.result.dt8_pk_saved!==true)throw new Error('The request was not confirmed. Please try again.');
    feedback.textContent='Your preferred time request has been received. Dalla Terra will confirm the session or suggest another time. No appointment has been booked yet.';
    button.textContent='Request received';button.disabled=true;
   }catch(err){feedback.textContent=err.message||'Unable to submit this request.';button.disabled=false;}
  });
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();
